void callback(char* topic, byte* payload, unsigned int length) {
  // ตรวจสอบว่าข้อความที่รับมาเป็นข้อมูลเวลาหรือไม่
  if (strcmp(topic, "@msg/timer/setHr") == 0) {
    receivedHour = safe_atoi((char *)payload);
  } else if (strcmp(topic, "@msg/timer/setMinute") == 0) {
    receivedMinute = safe_atoi((char *)payload);
  } else if (strcmp(topic, "@msg/timer/setSec") == 0) {
    receivedSecond = safe_atoi((char *)payload);
  }
}

int safe_atoi(const char *str) {
  char *endptr;
  errno = 0;    // To distinguish success/failure after call
  long val = strtol(str, &endptr, 10);

  // Check for various possible errors
  if ((errno == ERANGE && (val == LONG_MAX || val == LONG_MIN))
      || (errno != 0 && val == 0)) {
    perror("strtol");
    return 0;
  }

  if (endptr == str) {
    fprintf(stderr, "No digits were found\n");
    return 0;
  }

  if (*endptr != '\0') { // Not necessarily an error...
    fprintf(stderr, "Further characters after number: %s\n", endptr);
    return 0;
  }

  return (int)val;
}

